/**
 * Validates and normalizes status-change data received from the Join board.
 */
const input = $input.first().json;
const payload = input.body ?? input;

const allowedStatuses = [
  'triage',
  'toDo',
  'progress',
  'feedback',
  'done',
];

const statusLabels = {
  triage: 'Triage',
  toDo: 'To do',
  progress: 'In progress',
  feedback: 'Await feedback',
  done: 'Done',
};

const oldStatus = String(payload.oldStatus || '').trim();
const newStatus = String(payload.newStatus || '').trim();
const creatorEmail = String(payload.creatorEmail || '').trim().toLowerCase();

const validEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(creatorEmail);
const validStatus = allowedStatuses.includes(newStatus);

return [{
  json: {
    taskId: String(payload.taskId || ''),
    title: String(payload.title || 'Join-Ticket').trim().slice(0, 120),
    oldStatus,
    newStatus,
    newStatusLabel: statusLabels[newStatus] || newStatus,
    creatorName: String(payload.creatorName || 'Stakeholder').trim(),
    creatorEmail,
    creatorType: String(payload.creatorType || 'external'),
    shouldNotify:
      validEmail &&
      validStatus &&
      oldStatus !== newStatus,
  },
}];
